VAR_INPUT
    VISCOSITY_OK      : BOOL;
    PASTE_E_STOP_NC   : BOOL;
    DebounceMs        : DINT;
    CycleMs           : DINT;
END_VAR
VAR_OUTPUT
    VFD_RUN           : BOOL := FALSE;
    PUMP_MAINT_DUE    : BOOL := FALSE;
    PUMP_RUNTIME_ACC  : LINT := 0;
END_VAR
VAR
    DebounceAccum     : DINT := 0;
END_VAR

